'use strict';
// 1.0 rules: the fixed non-financial candidate tested in the 365-day study.
const BALANCE1={task:.35,event:.8,maintenance:1.5,demandStart:1.2,demand:2.2,demandRamp:60,weatherFrequency:1.3,weatherDuration:1.25,weatherLoss:1.25};
const CARD1_WEIGHTS=[[42,27,15,8,5,3],[36,26,17,10,7,4],[30,25,18,13,8,6],[25,23,19,15,10,8],[22,21,19,16,12,10]];
const CARD1_POWER=[1,1,1,1.15,1.25,1.5],CARD1_BONUS=[130,180,300,420,600,850];
const CARD1_PACK=[{},{bus:1},{bus:1,emu:1},{bus:2,emu:1,rail:1},{bus:2,emu:1,rail:1,air:1},{bus:4,emu:2,rail:1,air:1}];
const CARD1_LOAD=[20,35,60,100,160,230];
function balanceState(){return S.balance1??={power:1,dry:0,pityUsed:false,growth:{allUnlockedAt:null,awarded:{bus:0,emu:0,rail:0,air:0,hub:0}}};}
const fresh1Before=fresh;fresh=function(){let x=fresh1Before();x.release='1.0';x.lives=1;x.balance1={power:1,dry:0,pityUsed:false,growth:{allUnlockedAt:null,awarded:{bus:0,emu:0,rail:0,air:0,hub:0}}};x.climate.next=14/BALANCE1.weatherFrequency;return x;};
const credit1Before=credit;credit=function(amount,category,label){let factor=category==='tasks'?BALANCE1.task:category==='events'?BALANCE1.event:1;return credit1Before(Math.round(amount*factor*100)/100,category,label);};
Object.defineProperty(TYPES.bus,'vehicle',{configurable:true,get:()=>industryPrice(160)});
const rate1Before=passengerRate;passengerRate=function(c){let r=rate1Before(c);return remoteCity(c)?r:r*(BALANCE1.demandStart+Math.min(1,S.day/BALANCE1.demandRamp)*(BALANCE1.demand-BALANCE1.demandStart));};
const maintenance1Before=maintenanceAssets;maintenanceAssets=function(){return maintenance1Before().map(x=>({...x,monthly:x.monthly*BALANCE1.maintenance}));};
const climate1Before=updateClimate;updateClimate=function(oldDay){let before=new Set(S.climate.events.map(e=>e.id)),next=S.climate.next;climate1Before(oldDay);if(S.climate.next!==next)S.climate.next=S.day+(S.climate.next-S.day)/BALANCE1.weatherFrequency;for(let e of S.climate.events)if(!before.has(e.id)&&e.type!=='typhoon')e.end=e.start+(e.end-e.start)*BALANCE1.weatherDuration;};
const weather1Before=weatherFactor;weatherFactor=function(p,type){let stormActive=S.climate.events.some(e=>e.type==='typhoon'&&S.day>=e.start&&S.day<e.end);if(!stormActive){let f=weather1Before(p,type);return f===0?0:Math.max(.2,1-(1-f)*BALANCE1.weatherLoss);}let wet=1,storm=1;for(let e of S.climate.events){if(S.day<e.start||S.day>=e.end)continue;let pos=weatherCenter(e);if(Math.hypot(p.x-pos.x,p.y-pos.y)>e.radius)continue;let loss=e.type==='fog'?(type==='bus'?(e.strong?.3:.15):isTrain(type)?(e.strong?.15:.05):(e.strong?.5:.25)):e.type==='rain'?(type==='bus'?(e.strong?.25:.1):isTrain(type)?(e.strong?.15:.05):(e.strong?.35:.12)):(type==='bus'?.45:isTrain(type)?.25:1);if(e.type==='typhoon'&&type==='air')return 0;if(stationCoverage(p))loss*=.5;if(e.type==='typhoon')storm=Math.min(storm,1-loss);else wet=Math.min(wet,1-loss);}return Math.min(storm,Math.max(.2,1-(1-wet)*BALANCE1.weatherLoss));};
activityWeights=function(day=S.day){return CARD1_WEIGHTS[day<88?0:Math.min(4,1+Math.floor((day-88)/30))];};
activityRewardChoices=function(){return ['bus','emu','rail','air'].filter(t=>S.unlocked.includes(t)).map(type=>({type,label:TYPES[type].name+'线路名额＋1'})).concat([{type:'hub',label:'枢纽名额＋1'}]);};
const capacity1Before=vehCap;vehCap=function(v){return Math.ceil(capacity1Before(v)*balanceState().power);};
const hub1Before=hubLimit;hubLimit=function(){return hub1Before()+balanceState().growth.awarded.hub;};
function growTransport1(){let g=balanceState().growth;if(g.allUnlockedAt===null&&['bus','emu','rail','air'].every(t=>S.unlocked.includes(t)))g.allUnlockedAt=S.day;if(g.allUnlockedAt===null)return;for(let [type,period] of Object.entries({bus:125,emu:150,rail:150,air:180,hub:200})){let count=Math.floor((S.day-g.allUnlockedAt+1e-7)/period)-g.awarded[type];if(count>0){g.awarded[type]+=count;if(type!=='hub')S.limits[type]+=count;toast((type==='hub'?'枢纽':TYPES[type].name)+'可建名额＋'+count);}}}
function fitActivity1(e){e.rule1=true;e.bonus=CARD1_BONUS[e.star-1];e.generatedDay=S.day;e.specialFlip=e.star>=5||!!e.guaranteed;
 let routes=e.sources.map(id=>({id,time:plan(id,{origin:id,eventId:'task-preview',dest:e.host})?.time??Infinity})).filter(x=>Number.isFinite(x.time)).sort((a,b)=>a.time-b.time),near=routes.filter(x=>x.time<=120);if(!near.length)near=routes.slice(0,1);if(e.guaranteed)near=near.slice(0,3);e.sources=near.map(x=>x.id);e.routeMedian=near[Math.floor((near.length-1)*.5)]?.time||0;e.routeP90=near[Math.floor((near.length-1)*.9)]?.time||0;
 let age=Math.max(0,S.day-22),date=1+.002*Math.min(age,126)+.006*Math.max(0,age-126),scale=Math.max(.65,Math.min(1.15,60/(e.routeMedian+30))),u=Math.max(0,Math.min(1,(S.day-65)/83));e.baseLoad=e.guaranteed?({4:21,5:28}[e.star]):e.star===6?110+120*u*u:CARD1_LOAD[e.star-1];e.dateFactor=date;e.routeScale=scale;e.total=Math.max(6,Math.round(e.baseLoad*date*scale));e.goal=Math.ceil(e.total*(e.guaranteed?.6:.7));e.goodRatio=e.guaranteed?.6:.7;e.waitLimit=e.guaranteed?225:180;e.prepare=e.guaranteed?5:3;e.duration=Math.max(e.guaranteed?18:14,Math.min(28,Math.ceil(e.routeP90/12)+4));e.tailDays=Math.max(3,Math.min(e.duration-3,Math.ceil(e.routeP90/12)+1));e.fine=e.guaranteed?30:60;e.scoreLoss=0;return e;}
const card1Before=makeActivityCard;makeActivityCard=function(...args){return fitActivity1(card1Before(...args));};
const offers1Before=generateActivityOffers;generateActivityOffers=function(){let ok=offers1Before();if(!ok)return ok;let b=balanceState(),s=activityState();if(S.day>=180||b.pityUsed){b.dry=0;return ok;}let eligible=[4,5].filter(activityEligible);if(!eligible.length){b.dry=0;return ok;}let high=s.offers.some(e=>e.star>=4);if(!high&&b.dry>=3){let old=s.offers[2],weights=activityWeights(),r=Math.random()*eligible.reduce((n,star)=>n+weights[star-1],0),star=eligible.at(-1);for(let v of eligible){r-=weights[v-1];if(r<0){star=v;break;}}let e=card1Before(star,old.host,old.sources);e.guaranteed=true;fitActivity1(e);s.offers[2]=e;b.pityUsed=true;high=true;}b.dry=high?0:b.dry+1;save();return ok;};
const settle1Before=settleActivity;settleActivity=function(){let active=activityState().active,id=active?.id;settle1Before();let e=activityState().history[0];if(id&&e?.id===id&&e.rule1&&e.success&&!e.packPaid){e.packPaid=true;let b=balanceState();b.power=Math.max(b.power,CARD1_POWER[e.star-1]);for(let [type,count] of Object.entries(CARD1_PACK[e.star-1])){let extra=count-(e.vehicle===type?1:0);S.inventory[type]+=extra;for(let i=0;i<extra;i++)addStockAsset(type,{cars:isTrain(type)?2:1,investment:0});}save();}};
const updateActivities1Before=updateActivityCards;updateActivityCards=function(){let e=activityState().active;if(!e?.rule1)return updateActivities1Before();if(S.day>=e.end)return settleActivity();if(S.day>=e.start){let desired=Math.min(e.total,Math.floor(e.total*Math.min(1,(S.day-e.start)/Math.max(1,e.duration-e.tailDays))));while(e.spawned<desired){let id=e.sources[e.spawned%e.sources.length];if(S.cities[id]&&!S.cities[id].dormant)S.cities[id].q.push(activityPassenger(e,id));e.spawned++;}}};
activityRewardText=function(e){let pack=e.rule1?CARD1_PACK[e.star-1]:e.vehicle?{[e.vehicle]:1}:{},cash=Math.round(e.bonus*.8*100)/100;return '¥'+cash+' · 满意度＋'+(5+e.star)+Object.entries(pack).map(([type,n])=>' · '+TYPES[type].name+'×'+n).join('')+(e.rule1&&CARD1_POWER[e.star-1]>1?' · 全网载客容量×'+CARD1_POWER[e.star-1]:'')+(e.reward?' · '+e.reward.label:'');};
const cardHtml1Before=activityCardHTML;activityCardHTML=function(e,index=0){return cardHtml1Before(e,index).replace(' · 80%送达者候车≤120秒',' · '+Math.round(e.goodRatio*100)+'%送达者候车≤'+e.waitLimit+'秒').replace('class="activity-slot stars-','class="activity-slot '+(e.guaranteed?'has-special-flip ':'')+'stars-');};
const showActivities1Before=showActivityCards;showActivityCards=function(){showActivities1Before();let el=$('modal-content'),e=activityState().active;el.innerHTML=el.innerHTML.replace('线路最多额外＋3/车型，枢纽最多额外＋2，名额仍需自费建设。','线路与枢纽名额可持续增长，增加名额后仍需自费建设。');if(e)el.innerHTML=el.innerHTML.replace('要求80%','要求'+Math.round(e.goodRatio*100)+'%');};
const tick1Before=tick;tick=function(dt){tick1Before(dt);growTransport1();};
const load1Before=load;load=function(){let ok=load1Before();if(ok){balanceState();S.release='1.0';S.lives=Math.min(1,S.lives);save();}return ok;};
welcome=function(hasSave){openModal(`<div class="ux-hero"><span class="eyebrow">东岸 · 1.0 城市与金融</span><h1>连接城市，经营未来。</h1><p class="ux-lead">拖动建设线路，安排运力，让城市在你的交通网络中成长。</p></div><ul class="ux-points"><li><i>¥</i><span><b>起步500 · 每10天补助100</b>大巴基础价160，建设费用按报价结算</span></li><li><i>♥</i><span><b>一条生命，长期经营</b>满员压力达到阈值才扣命；暂停可从容规划</span></li><li><i>★</i><span><b>城市邀请与成长奖励</b>完成高星任务，获得车辆、载客容量和新名额</span></li><li><i>↗</i><span><b>独立金融市场</b>中级金融城建银行理财，高级金融城开放股票</span></li></ul><div class="ux-actions"><button class="primary ux-wide" onclick="startGame()">${hasSave?'继续经营':'开始经营'}</button>${hasSave?'<button class="ux-ghost" onclick="uxConfirmNew(this)">重新开始</button>':''}</div><p class="ux-foot">每游戏日12秒 · <a href="../updates/">1.0更新说明</a> · 新开局使用完整1.0规则；旧存档保留原有资产与正在进行的任务。</p>`);};
const help1Before=help;help=function(){help1Before();$('modal-content').innerHTML=`<div class="modal-head"><h2>东岸1.0 · 调度手册</h2><button class="close" onclick="closeModal()">×</button></div><p>开局500、一条命；每10天固定补助100。拖动城市修建线路，点击线路配车、扩编、设置区间或快车。新增路段按报价建设，跨河先修桥，山地按报价修隧道。</p><p>候客厅满员会积累拥堵压力，普通城市180模拟秒、旅游城市225秒扣命；活动专属乘客不计普通满员压力。及时加车、缩短绕行，并留意雾雨、台风与地震。气象站可以缓解覆盖区内的天气减速。</p><p>城市任务、真实送达带来成长与收入，维护费月底结算。资金不足记欠费，后续收入自动补缴。高星活动可提高全网载客容量，重复奖励取最高档而不叠加。</p><p>全部交通方式实际解锁后，公交每125天、动车和高铁每150天、航空每180天、枢纽每200天各增加1个名额；六星额外名额可继续累计，均需自费建设。</p><p>中大城市可建学校与检修中心：学校正常运营且评价优良时，所连接设施维护费减免10%；检修中心按覆盖范围缩短新开工工程时间。城市长期差评会降级，改善服务可逐步恢复。</p><p>中级商业金融城可建银行100，高级可建证券公司150。底栏「金融」始终显示，未解锁时点击可查看建设条件；银行建成后开放金融市场；证券公司建成后股票开市，每游戏日09:00更新。理财次日可取，涨跌与收益以百分比显示。</p><div class="ux-actions">${financeUnlocked()?'<button onclick="showFinancialMarket()">金融市场</button>':''}<button onclick="showFinance()">交通账本</button><a href="../updates/">更新说明</a></div>`;};
$('help').onclick=()=>help();
